INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m12451$nota-0032$m12451$, $m12452$Training and Racing with a Power Meter.pdf$m12452$, $m12453$71$m12453$, $m12454$The Power Profile indexes efforts of 5 seconds, 1 minute, and 5 minutes and a fourth measure at functional threshold power in an attempt to best reflect neuromuscular power, anaerobic capacity, maximal oxygen uptake (VO2max), and lactate threshold (LT), respectively.$m12454$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m12455$nota-0032$m12455$, $m12456$Training and Racing with a Power Meter.pdf$m12456$, $m12457$71$m12457$, $m12458$roughly 40–45 percent of the energy expended during such exercise [1-min all-out] is derived aerobically... [anaerobic capacity] generally requires 1.5–2.5 minutes to deplete... most athletes can sustain a power that would elicit 105–110 percent of their VO2max for [5 minutes].$m12458$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m12459$nota-0034$m12459$, $m12460$Training and Racing with a Power Meter.pdf$m12460$, $m12461$73$m12461$, $m12462$The majority of your warm-up should be in Levels 2 and 3... Complete at least 10 minutes of easy pedaling before the first effort. For the test efforts, do not worry about cadence, heart rate, or anything else—all that matters is the clock, so drive hard to the end of each timed effort.$m12462$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m12463$nota-0034$m12463$, $m12464$Training and Racing with a Power Meter.pdf$m12464$, $m12465$73$m12465$, $m12466$Finish with a short cooldown to get in at least another 300–500 kilojoules of Level 2 riding.$m12466$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m12467$nota-0034$m12467$, $m12468$nota-0020$m12468$, $m12469$complementa$m12469$, $m12470$junto com o teste de FTP de 20 minutos, completa o perfil de potência do atleta nas 4 durações-índice$m12470$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m12471$nota-0038$m12471$, $m12472$Training and Racing with a Power Meter.pdf$m12472$, $m12473$83$m12473$, $m12474$Be sure to revise your chart every four to six weeks and note changes from the previous training block. This is an excellent way to make sure all your hard work is going in the right places.$m12474$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m12475$nota-0038$m12475$, $m12476$nota-0021$m12476$, $m12477$complementa$m12477$, $m12478$cadência de reavaliação semelhante (mas não idêntica) à recomendação de reteste de FTP a cada 6-8 semanas$m12478$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m12479$nota-0051$m12479$, $m12480$Training and Racing with a Power Meter.pdf$m12480$, $m12481$124$m12481$, $m12482$if you look at a large enough dataset that includes time spent at and above FTP, you can see where the heart rate threshold would be. Set the data range set to three to five heartbeats per minute to more easily see where the step-down occurs.$m12482$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m12483$nota-0051$m12483$, $m12484$nota-0025$m12484$, $m12485$complementa$m12485$, $m12486$é o análogo, para FC, do método de distribuição de frequência de potência para estimar FTP (nota-0025)$m12486$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m12487$nota-0058$m12487$, $m12488$Training and Racing with a Power Meter.pdf$m12488$, $m12489$150$m12489$, $m12490$See how many kilojoules of energy you used during your ride and determine whether you refueled enough... View your Quadrant Analysis... Determine when your wattage began to decrease during the ride. How many kilojoules of energy had you expended up to this point?$m12490$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m12491$nota-0058$m12491$, $m12492$Training and Racing with a Power Meter.pdf$m12492$, $m12493$150$m12493$, $m12494$View the matches burned in a race... Look for your peaks and determine where they are in the file... If you got dropped, see what types of efforts you had to do, the number of watts for these efforts, and where the breaking point was.$m12494$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m12495$nota-0058$m12495$, $m12496$nota-0002$m12496$, $m12497$complementa$m12497$, $m12498$usa a conversão kJ→kcal (nota-0002) para checar se o reabastecimento foi suficiente$m12498$)
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m12499$nota-0058$m12499$, $m12500$nota-0055$m12500$, $m12501$complementa$m12501$, $m12502$usa o conceito de matches (nota-0055) para entender a demanda da prova$m12502$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m12503$nota-0072$m12503$, $m12504$Training and Racing with a Power Meter.pdf$m12504$, $m12505$187$m12505$, $m12506$on four different days you will complete three 5-minute intervals at your Level 5 (VO2max) power (roughly 113–115 percent of your FTP). For the first interval, stand up on the pedals the entire time, for the second interval stay seated the entire time, and for the third interval alternate standing and sitting.$m12506$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m12507$nota-0072$m12507$, $m12508$Training and Racing with a Power Meter.pdf$m12508$, $m12509$187$m12509$, $m12510$Day 1: Complete the test with no emphasis on either leg... Day 2: Emphasize the leg that releases less power... Day 3: Emphasize the left leg only... Day 4: Emphasize the right leg only.$m12510$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m12511$nota-0072$m12511$, $m12512$nota-0071$m12512$, $m12513$pre-requisito$m12513$, $m12514$o teste é analisado usando as métricas GPR/GPA definidas na nota-0071$m12514$)
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m12515$nota-0072$m12515$, $m12516$nota-0011$m12516$, $m12517$complementa$m12517$, $m12518$investiga a mesma assimetria entre pernas discutida na nota-0011, mas de forma diagnóstica/comportamental (técnica) em vez de apenas um viés de medição$m12518$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m12519$nota-0075$m12519$, $m12520$Training and Racing with a Power Meter.pdf$m12520$, $m12521$197$m12521$, $m12522$if you compete in criteriums and often go for primes, you may perform a personal best effort for 50 seconds... the mean maximal power for 1 minute will be low and not truly indicative of your anaerobic capacity power as stipulated by the Power Profile chart.$m12522$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m12523$nota-0075$m12523$, $m12524$Training and Racing with a Power Meter.pdf$m12524$, $m12525$198$m12525$, $m12526$FTP represents an intensity that can be sustained for between perhaps 30 and 70 minutes... a 40 km TT may last approximately 60 minutes for most individuals, it will almost never last exactly 60 minutes.$m12526$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m12527$nota-0075$m12527$, $m12528$nota-0031$m12528$, $m12529$contradiz$m12529$, $m12530$expõe uma limitação metodológica do próprio Power Profile de 4 durações fixas (nota-0031), motivando o modelo Potência-Duração como alternativa mais robusta$m12530$)
